(() => {
 const data=window.NERAM_BENGALURU,core=window.NeramBengaluruCore,stations=core.stations(data),host=$('#bengaluru-view');
 const lines=new Map(data.lines.map(l=>[l.line_id,l]));
 host.innerHTML=`<div class="metro-intro"><div class="metro-kicker">BENGALURU · NAMMA METRO</div><h1 id="bengaluru-heading">Find your way across Bengaluru.</h1><p>Three lines. One connected journey.</p></div>
 <div class="bl-overview"><span><strong>${stations.length}</strong> stations</span><span><strong>3</strong> lines</span><span><strong>2</strong> interchanges</span></div>
 <p class="bl-notice">Route guide from the uploaded ixigo catalog, retrieved 27 October 2026. Service hours are approximate line summaries. Confirm with BMRCL before travelling.</p>
 <form id="bl-form" class="metro-planner"><div class="metro-station-inputs"><div class="metro-select"><label for="bl-from">From</label><select id="bl-from"></select></div><button id="bl-swap" class="icon-button swap" type="button" aria-label="Swap Bengaluru stations">${icon('swap')}</button><div class="metro-select"><label for="bl-to">To</label><select id="bl-to"></select></div></div><button class="search-button" type="submit">${icon('route')}<span>Find Metro route</span></button><p id="bl-error" class="form-error" role="alert" hidden>Choose two different stations.</p></form>
 <section id="bl-result" class="metro-route-result" aria-label="Bengaluru journey"><div class="metro-detail-kicker">YOUR METRO JOURNEY</div><h2 id="bl-route-title"></h2><p id="bl-route-summary" role="status" aria-live="polite"></p><div id="bl-legs"></div><p class="metro-source-note">Fares and journey times are unavailable in this file. The route prioritizes fewer line changes, then fewer station intervals.</p></section>
 <section class="bl-hours metro-route-result"><div class="bl-hours-heading"><div><p class="metro-detail-kicker">PLAN YOUR DAY</p><h2>Approximate service hours</h2></div><label for="bl-day" class="sr-only">Service day</label><select id="bl-day"><option value="monday_to_saturday">Monday–Saturday</option><option value="sunday">Sunday</option></select></div><div id="bl-hours"></div><p class="metro-source-note">Catalog claim for Purple/Green peak frequency: every 8 minutes, during 07:00–10:00 and 17:00–21:00. Frequency may vary. These are line-level first/last train summaries, not departures from your selected station. This catalog has no station timetable or live train data.</p></section>
 <details class="metro-catalogue"><summary>Explore lines & stations</summary><div class="metro-catalogue-content"><label for="bl-line">Metro line</label><select id="bl-line" class="bl-filter"></select><label for="bl-query" class="sr-only">Search Bengaluru stations</label><div class="metro-station-search">${icon('search')}<input id="bl-query" type="search" placeholder="Search station name" autocomplete="off"></div><p id="bl-count" class="metro-source-note" role="status"></p><ol id="bl-stations" class="bl-stations"></ol></div></details>
 <p class="metro-source-note">Source: <a href="https://www.ixigo.com/metro/bengaluru/route-map" target="_blank" rel="noopener noreferrer">ixigo route map</a> · Third-party catalog, not an official BMRCL timetable. Station coordinates and a geographic route map were not supplied.</p>`;
 for(const id of ['#bl-from','#bl-to'])for(const station of stations){const o=new Option(station,station);$(id).add(o);}
 $('#bl-from').value=stations[0];$('#bl-to').value=data.lines.at(-1).stations_in_order.at(-1);
 const badge=(line)=>{const b=textNode('span',line.line_name,'bl-badge bl-'+line.line_id);return b;};
 function renderRoute(){const from=$('#bl-from').value,to=$('#bl-to').value,result=core.route(data,from,to);$('#bl-error').hidden=!!result;$('#bl-result').hidden=!result;if(!result)return;
  $('#bl-route-title').textContent=`${from} → ${to}`;$('#bl-route-summary').textContent=`${result.stations.length} stations · ${result.hops} station interval${result.hops===1?'':'s'} · ${result.transfers?result.transfers+' line change'+(result.transfers>1?'s':''):'Direct route'}`;
  const el=$('#bl-legs');el.replaceChildren();result.legs.forEach((leg,i)=>{const line=lines.get(leg.line),section=document.createElement('section');section.className='bl-leg';section.append(badge(line));const forward=line.stations_in_order.indexOf(leg.stations[0])<line.stations_in_order.indexOf(leg.stations.at(-1));section.append(textNode('p',`Towards ${forward?line.stations_in_order.at(-1):line.stations_in_order[0]}`,'bl-direction'));
   if(i)section.prepend(textNode('p',`Change to ${line.line_name} at ${leg.stations[0]}`,'bl-transfer'));
   const list=document.createElement('ol');list.className='bl-stations';leg.stations.forEach((station,j)=>{const li=textNode('li',station);if(j===0||j===leg.stations.length-1)li.className='bl-endpoint';list.append(li);});if(leg.stations.length>6){const ends=textNode('p',`${leg.stations[0]} → ${leg.stations.at(-1)}`,'bl-leg-endpoints'),details=document.createElement('details');details.className='bl-leg-details';details.append(textNode('summary',`Show all ${leg.stations.length} stations`),list);section.append(ends,details);}else section.append(list);el.append(section);});
 }
 function hours(){const day=$('#bl-day').value,el=$('#bl-hours');el.replaceChildren();data.lines.forEach(line=>{const row=document.createElement('div');row.className='bl-hour-row';row.append(badge(line),textNode('span',`${line.first_train[day]} – ${typeof line.last_train==='string'?line.last_train:line.last_train[day]}`));el.append(row);});}
 for(const line of data.lines)$('#bl-line').add(new Option(line.line_name,line.line_id));
 function catalogue(){const line=lines.get($('#bl-line').value),q=$('#bl-query').value.toLowerCase().trim(),el=$('#bl-stations');el.replaceChildren();const found=line.stations_in_order.filter(s=>s.toLowerCase().includes(q));$('#bl-count').textContent=`${found.length} of ${line.station_count} stations · ${line.distance_km} km line length (catalog)`;found.forEach(station=>{const li=document.createElement('li');li.append(textNode('span',station));const serving=data.lines.filter(l=>l.stations_in_order.includes(station));if(serving.length>1){const badges=document.createElement('span');badges.className='bl-interchange';serving.forEach(l=>badges.append(badge(l)));li.append(badges);}el.append(li);});if(!found.length)$('#bl-count').textContent='No matching stations.';}
 $('#bl-form').addEventListener('submit',e=>{e.preventDefault();renderRoute();if(!$('#bl-result').hidden)$('#bl-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
 for(const id of ['#bl-from','#bl-to'])$(id).addEventListener('change',renderRoute);
 $('#bl-swap').addEventListener('click',()=>{const from=$('#bl-from').value;$('#bl-from').value=$('#bl-to').value;$('#bl-to').value=from;renderRoute();});
 $('#bl-day').addEventListener('change',hours);$('#bl-line').addEventListener('change',catalogue);$('#bl-query').addEventListener('input',catalogue);
 function city(){const bl=location.hash==='#metro-bengaluru';$('#metro-city').value=bl?'bengaluru':'kochi';host.hidden=!bl;$('#kochi-view').hidden=bl;}
 $('#metro-city').addEventListener('change',()=>{location.hash=$('#metro-city').value==='bengaluru'?'metro-bengaluru':'metro';});
 window.addEventListener('hashchange',city);window.addEventListener('neram:metro-mode',city);
 renderRoute();hours();catalogue();city();
})();
